"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _check_inside(spans: List[Span], hours: Span) -> None:
    for span in spans:
        if span.start < hours.start or span.end > hours.end:
            raise ValueError(
                f"{format_span(span)} is outside hours"
            )

def _uncovered(spans: List[Span], hours: Span):
    merged = merge_spans(spans)
    starts = [hours.start] + [s.end for s in merged]
    ends = [s.start for s in merged] + [hours.end]
    return [
        Span(a, b) for a, b in zip(starts, ends) if a < b
    ]

def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"

# ---
def find_gaps(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """One label per uncovered stretch of the day."""
    spans = list(worked)
    _check_inside(spans, hours)
    gaps = _uncovered(spans, hours)
    return [_label(gap) for gap in gaps]

