import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

HOURS = parse_span("09:00-17:00")

def gaps_for(*texts):
    return find_gaps([parse_span(t) for t in texts], HOURS)

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            gaps_for("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(gaps_for("09:00-17:00"), [])

    def test_touching_and_overlapping_leave_no_gap(self):
        spans = ["9:00-12:00", "12:00-14:00", "13:00-17:00"]
        self.assertEqual(gaps_for(*spans), [])

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            gaps_for("10:00-16:00"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(
            gaps_for(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_unordered_input(self):
        self.assertEqual(
            gaps_for("14:00-17:00", "09:00-10:30"),
            ["gap 10:30-14:00 (210 min)"]
        )

    def test_span_starting_too_early_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-12:00")

    def test_span_ending_too_late_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("09:00-12:00", "16:00-17:30")
